# Example of a simple function
def multiply(x, y):
    return x * y

# Example of a test with an assertion
def test_multiply():
    assert multiply(2, 3) == 6

# Example of another test function
def test_subtract():
    assert subtract(5, 3) == 2

# Example function definition
def greet(name):
    return "Hello, " + name

# Example: grouping related tests in a class
class TestStringOperations:
    def test_concatenate(self):
        assert 'hello' + 'world' == 'helloworld'

# Example of a pytest fixture
import pytest

@pytest.fixture
def sample_numbers():
    return {'a': 5, 'b': 3, 'expected': 8}

# Test using the fixture
def test_addition(sample_numbers):
    result = add(sample_numbers['a'], sample_numbers['b'])
    assert result == sample_numbers['expected']
